/* Generated loader for Excel-derived article formulas. */
window.GATE_CALC_MODELS_READY=(async()=>{
  const b64=window.__GATE_CALC_B64||'';
  if(!b64) throw new Error('Не загружены данные расчётных моделей');
  const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));
  if(!('DecompressionStream' in window)) throw new Error('Браузер не поддерживает распаковку модели расчёта');
  const text=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
  (0,eval)(text);
  if (window.GATE_CALC_MODELS?.models) {
    for (const article of ['39','40']) delete window.GATE_CALC_MODELS.models[article];
  }
  delete window.__GATE_CALC_B64;
  return window.GATE_CALC_MODELS;
})();

/* Mobile UX: selecting a gate must continue the catalog flow instead of opening
   a full-screen pseudo-modal. app.js already places the calculator immediately
   after the selected catalog row, so keep that natural inline placement. */
(() => {
  if (document.getElementById('kuzdvorInlineCalculatorOverride')) return;
  const style=document.createElement('style');
  style.id='kuzdvorInlineCalculatorOverride';
  style.textContent=`
    @media(max-width:620px){
      html body.calculator-open{overflow-x:hidden!important;overflow-y:auto!important}
      .calculator.inline-calculator:not([hidden]).inline-calculator{
        position:relative!important;inset:auto!important;z-index:1!important;
        width:calc(100% - 20px)!important;height:auto!important;max-width:620px!important;
        margin:16px auto 26px!important;padding:10px 10px 82px!important;
        overflow:visible!important;overscroll-behavior:auto!important;-webkit-overflow-scrolling:auto!important;
        background:#0c0d0f!important;border-radius:18px!important;box-sizing:border-box!important;
        scroll-margin-top:10px!important;
      }
      .calculator.inline-calculator:not([hidden]).inline-calculator>.section-head{display:none!important}
      .calculator.inline-calculator:not([hidden]).inline-calculator .calculator-layout{
        display:block!important;width:100%!important;max-width:620px!important;margin:0 auto!important
      }
      .calculator.inline-calculator:not([hidden]).inline-calculator .calc-form{
        margin:0!important;padding:10px!important;border-radius:16px!important
      }
      .calculator.inline-calculator:not([hidden]).inline-calculator .selected-product-preview{
        position:relative!important;top:auto!important;z-index:auto!important;
        margin:0 0 12px!important;padding:8px 54px 8px 8px!important;box-shadow:none!important
      }
      .calculator.inline-calculator:not([hidden]).inline-calculator .change-product{
        position:absolute!important;top:10px!important;right:10px!important;bottom:auto!important;left:auto!important;
        width:38px!important;height:38px!important;min-height:38px!important;margin:0!important;padding:0!important;
        display:grid!important;place-items:center!important;border:1px solid rgba(255,255,255,.16)!important;
        border-radius:50%!important;background:rgba(255,255,255,.06)!important;color:#f0c96f!important;
        font:400 28px/1 Arial,sans-serif!important;text-align:center!important;cursor:pointer!important
      }
    }
  `;
  document.head.append(style);

  const decorateCloseButton=()=>{
    const button=document.getElementById('changeProductButton');
    if(!button)return null;
    if(button.textContent!=='×')button.textContent='×';
    button.setAttribute('aria-label','Закрыть расчёт');
    button.setAttribute('title','Закрыть расчёт');
    return button;
  };
  const closeButton=decorateCloseButton();
  if(closeButton){
    new MutationObserver(()=>decorateCloseButton()).observe(closeButton,{childList:true,subtree:true});
  }else{
    const observer=new MutationObserver(()=>{
      if(decorateCloseButton())observer.disconnect();
    });
    observer.observe(document.documentElement,{childList:true,subtree:true});
  }
})();

/* Standalone gate calculator. Excel-derived formulas are the only source of gate prices. */
(() => {
  const prices = window.GATE_CALC_PRICES;
  if (!prices) throw new Error('Не загружены общие цены расчёта ворот');

  const normalizeArticle = value => String(value ?? '')
    .replace(/^\s*арт\.?\s*/iu, '')
    .replace(/c/giu, 'с')
    .trim()
    .toUpperCase();

  const roundExcel = (value, digits = 0) => {
    const x = Number(value);
    const d = Math.trunc(Number(digits) || 0);
    if (!Number.isFinite(x)) return NaN;
    const factor = 10 ** Math.abs(d);
    const scaled = d >= 0 ? x * factor : x / factor;
    const rounded = scaled >= 0 ? Math.floor(scaled + 0.5) : Math.ceil(scaled - 0.5);
    return d >= 0 ? rounded / factor : rounded * factor;
  };

  const roundUp = (value, digits = 0) => {
    const x = Number(value);
    const d = Math.trunc(Number(digits) || 0);
    if (!Number.isFinite(x)) return NaN;
    const factor = 10 ** Math.abs(d);
    if (d >= 0) return (x >= 0 ? Math.ceil(x * factor) : Math.floor(x * factor)) / factor;
    return (x >= 0 ? Math.ceil(x / factor) : Math.floor(x / factor)) * factor;
  };

  const sum = value => Array.isArray(value) ? value.reduce((acc, item) => acc + Number(item || 0), 0) : Number(value || 0);
  const compiled = new WeakMap();
  const pack = () => window.GATE_CALC_MODELS;

  const compileModel = model => {
    if (compiled.has(model)) return compiled.get(model);
    const result = {};
    for (const [ref, expr] of Object.entries(model.formulas || {})) {
      result[ref] = new Function('ctx','p','v','sum','roundExcel','roundUp', `return (${expr});`);
    }
    compiled.set(model, result);
    return result;
  };

  function rawGateCalculation({ article, gateWidth, gateHeight, wicketWidth, wicketHeight }) {
    const key = normalizeArticle(article);
    const model = pack()?.models?.[key];
    if (!model) throw new Error(`Нет расчётной модели для артикула ${article}`);

    const ctx = {
      gateWidth: Number(gateWidth),
      gateHeight: Number(gateHeight),
      wicketWidth: Number(wicketWidth),
      wicketHeight: Number(wicketHeight),
    };
    for (const [name, value] of Object.entries(ctx)) {
      if (!Number.isFinite(value) || value <= 0) throw new Error(`Некорректный размер: ${name}`);
    }

    const cache = { ...(model.literals || {}) };
    const formulas = compileModel(model);
    const p = ref => Number(prices[ref]?.value ?? 0);
    const v = ref => {
      if (Object.prototype.hasOwnProperty.call(cache, ref)) return cache[ref];
      const fn = formulas[ref];
      if (!fn) throw new Error(`Не найдена формула ${key}:${ref}`);
      const value = Number(fn(ctx, p, v, sum, roundExcel, roundUp));
      if (!Number.isFinite(value)) throw new Error(`Ошибка расчёта ${key}:${ref}`);
      cache[ref] = value;
      return value;
    };

    const gatePrice = v(model.gateRef);
    const wicketPrice = v(model.wicketRef);
    const totalRaw = gatePrice + wicketPrice;
    const total = roundExcel(totalRaw, -2);
    return { article: key, gatePrice, wicketPrice, totalRaw, total };
  }

  function standardDimensions(model) {
    const standard = model?.standard || {};
    return {
      gateWidth: Number(standard.gate_width_m) || 3.4,
      gateHeight: Number(standard.gate_height_m) || 1.8,
      wicketWidth: Number(standard.wicket_width_m) || 1,
      wicketHeight: Number(standard.wicket_height_m) || 1.8
    };
  }

  function calculateGate(input) {
    return rawGateCalculation(input);
  }

  function standardForArticle(article) {
    const key = normalizeArticle(article);
    const model = pack()?.models?.[key];
    if (!model) return null;
    const dimensions = standardDimensions(model);
    const calculation = rawGateCalculation({article, ...dimensions});
    return {...dimensions, price:calculation.total};
  }

  function hasArticle(article) { return Boolean(pack()?.models?.[normalizeArticle(article)]); }
  const ready = Promise.resolve(window.GATE_CALC_MODELS_READY).then(() => true);
  window.GATE_CALC = { calculateGate, standardForArticle, hasArticle, normalizeArticle, roundExcel, roundUp, ready };
})();
(() => {
  if (window.KUZDVOR_FORMULA_PRICE_SYNC_READY) return;
  window.KUZDVOR_FORMULA_PRICE_SYNC_READY = true;

  const roundMoney100 = value => Math.round((Number(value) || 0) / 100) * 100;
  const money = value => new Intl.NumberFormat('ru-RU').format(roundMoney100(value)) + ' ₽';
  const idForArticle = art => `catalog-${String(art||'').replace(/^Арт\.\s*/,'').toLowerCase().replace('с','s')}`;
  const standardInput = art => ({article:art,gateWidth:3.4,gateHeight:1.8,wicketWidth:1,wicketHeight:1.8});
  const normalizeCity = value => String(value || '').trim().toLocaleLowerCase('ru-RU').replace(/ё/g,'е');

  function formulaPrice(art) {
    if (!window.GATE_CALC?.hasArticle(art)) return null;
    try { return Number(window.GATE_CALC.calculateGate(standardInput(art)).total); }
    catch { return null; }
  }

  function deliveryContext() {
    const state = window.GATE_PAGE_API?.deliveryState?.() || {kind:'empty'};
    const kind = String(state.kind || 'empty');
    const city = String(state.city || state.shortName || state.resolvedName || state.name || document.getElementById('cityInput')?.value || '').trim();
    const confirmed = kind === 'fixed' || kind === 'calculated';
    const priced = confirmed || kind === 'confirm';
    return {kind, city, confirmed, priced, price:priced ? (Number(state.price) || 0) : 0};
  }

  function syncProducts() {
    const catalog = Array.isArray(window.PRICE_DATA?.catalog) ? window.PRICE_DATA.catalog : [];
    const api = window.GATE_PAGE_API;
    let cheapest = null;
    const installation = Number(window.PRICE_DATA?.catalogInstallation) || 0;
    const posts = Number(window.PRICE_DATA?.catalogPosts) || 0;

    for (const item of catalog) {
      if (item?.visible === false) continue;
      const price = formulaPrice(item.art);
      if (!Number.isFinite(price)) continue;
      item.price = price;
      const product = api?.productById?.(idForArticle(item.art));
      if (product) product.price = price;
      if (!cheapest || price < cheapest) cheapest = price;
    }

    if (Number.isFinite(cheapest)) {
      const installed = document.getElementById('heroInstalledPrice');
      const turnkey = document.getElementById('heroTurnkeyPrice');
      const installedText = `от ${money(cheapest + installation)}`;
      const turnkeyText = `от ${money(cheapest + installation + posts)}`;
      if (installed && installed.textContent !== installedText) installed.textContent = installedText;
      if (turnkey && turnkey.textContent !== turnkeyText) turnkey.textContent = turnkeyText;
    }
    syncVisibleCards();
  }

  function syncVisibleCards() {
    const delivery = deliveryContext();
    document.querySelectorAll('[data-card-product]').forEach(card => {
      const art = card.querySelector('.product-art')?.textContent?.trim();
      if (!art) return;
      const price = formulaPrice(art);
      if (!Number.isFinite(price)) return;
      const rows = card.querySelectorAll('.price-row strong');
      const installation = Number(window.PRICE_DATA?.catalogInstallation) || 0;
      const posts = Number(window.PRICE_DATA?.catalogPosts) || 0;
      const installedText = money(price + installation + delivery.price);
      const turnkeyText = money(price + installation + posts + delivery.price);
      if (rows[0] && rows[0].textContent !== installedText) rows[0].textContent = installedText;
      if (rows[1] && rows[1].textContent !== turnkeyText) rows[1].textContent = turnkeyText;

      const note = card.querySelector('.price-delivery-note');
      if (!note) return;
      let noteText = 'Доставка рассчитывается после выбора места установки';
      if (delivery.confirmed) {
        noteText = normalizeCity(delivery.city) === 'мелеуз'
          ? '✓ Доставка по Мелеузу бесплатно — уже учтена в цене'
          : `✓ С учётом доставки в ${delivery.city}`;
      } else if (delivery.kind === 'confirm') {
        noteText = delivery.city
          ? `≈ С учётом доставки в ${delivery.city} · подтвердите пункт`
          : '≈ Доставка уже учтена · подтвердите населённый пункт';
      } else if (delivery.kind === 'out-of-area' || delivery.kind === 'error') {
        noteText = delivery.city
          ? `Доставка в ${delivery.city} уточняется отдельно`
          : 'Стоимость доставки уточняется отдельно';
      } else if (delivery.kind === 'loading' || delivery.kind === 'pending') {
        noteText = delivery.city
          ? `Считаем доставку в ${delivery.city} — пока показана цена без доставки`
          : 'Считаем доставку — пока показана цена без доставки';
      }
      if (note.textContent !== noteText) note.textContent = noteText;
    });
  }

  let syncQueued = false;
  const scheduleSync = () => {
    if (syncQueued) return;
    syncQueued = true;
    requestAnimationFrame(() => {
      syncQueued = false;
      syncVisibleCards();
    });
  };

  const syncBurst = () => {
    scheduleSync();
    [50, 180, 500, 1200].forEach(delay => setTimeout(scheduleSync, delay));
  };

  const start = async () => {
    try {
      await Promise.resolve(window.GATE_CALC?.ready);
      syncProducts();
      const grid = document.getElementById('catalogGrid');
      if (grid) {
        new MutationObserver(records => {
          const priceWasTouched = records.some(record => {
            const target = record.target?.nodeType === 1 ? record.target : record.target?.parentElement;
            if (target?.closest?.('.price-row strong')) return true;
            return [...record.addedNodes].some(node => node.nodeType === 1 && (node.matches?.('[data-card-product]') || node.querySelector?.('[data-card-product]')));
          });
          if (priceWasTouched) scheduleSync();
        }).observe(grid, {childList:true,subtree:true,characterData:true});
      }

      // Delivery changes are emitted by the calculator. A short retry burst also
      // wins against late Excel/site-settings refreshes that may rewrite base-only
      // prices after the delivery calculation has already finished.
      document.addEventListener('gate:calculated', syncBurst);
      window.addEventListener('pageshow', syncBurst);

      // Final safety net for mobile browsers / restored tabs: while delivery has a
      // real price, visible cards are periodically reconciled with that same state.
      setInterval(() => {
        if (document.hidden) return;
        if (deliveryContext().priced) syncVisibleCards();
      }, 750);
    } catch (error) { console.error('Excel formula price sync failed', error); }
  };
  start();
})();
